import React from 'react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { act, cleanup, fireEvent, render, screen } from '@testing-library/react';
import { ProcessingScreen } from '@/components/ProcessingScreen';

const settings = { preferences: { defaultExportMode: 'governance' } };
vi.mock('@/components/Settings', () => ({ useSettings: () => ({ settings, isLoaded: true }) }));
vi.mock('@/lib/i18n', () => ({ useLanguage: () => ({ language: 'en' }) }));
vi.mock('@/lib/enforcement-log', () => ({ logEnforcementDecision: vi.fn() }));
vi.mock('@/lib/analytics', () => ({ trackEvent: vi.fn() }));
const inputs = { topic: 'synthetic task A' };
const props = { templateId: 'test', templateName: 'Test', inputs, intent: 'Synthetic offline A' };
const response = (badge = false) => ({ json: async () => ({ success: true, output: 'OUTPUT_A', ...(badge ? { enforcement: { status: 'ALLOW', riskGate: { riskLevel: 'R1' } } } : {}) }) });

describe('Local dispatch: actual ProcessingScreen lifecycle', () => {
  beforeEach(() => { vi.useFakeTimers(); });
  afterEach(() => { cleanup(); vi.clearAllTimers(); vi.useRealTimers(); vi.unstubAllGlobals(); });

  it('positive control: uncancelled real-shaped response completes once without a badge', async () => {
    const onComplete = vi.fn();
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(response()));
    render(<ProcessingScreen {...props} onComplete={onComplete} onCancel={vi.fn()} />);
    await act(async () => { await vi.advanceTimersByTimeAsync(1000); });
    expect(onComplete).toHaveBeenCalledTimes(1);
    expect(onComplete).toHaveBeenCalledWith('OUTPUT_A', undefined);
  });

  it('does not deliver a delayed result after unmount', async () => {
    const onComplete = vi.fn();
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(response()));
    const view = render(<ProcessingScreen {...props} onComplete={onComplete} onCancel={vi.fn()} />);
    await act(async () => { await vi.advanceTimersByTimeAsync(1); });
    view.unmount();
    await act(async () => { await vi.advanceTimersByTimeAsync(1000); });
    expect(onComplete).not.toHaveBeenCalled();
  });

  it('ignores a response arriving after explicit cancel even if parent stays mounted', async () => {
    let resolve!: (value: ReturnType<typeof response>) => void;
    const pending = new Promise<ReturnType<typeof response>>(r => { resolve = r; });
    const onComplete = vi.fn(); const onCancel = vi.fn();
    vi.stubGlobal('fetch', vi.fn().mockReturnValue(pending));
    render(<ProcessingScreen {...props} onComplete={onComplete} onCancel={onCancel} />);
    await act(async () => { await vi.advanceTimersByTimeAsync(1); });
    fireEvent.click(screen.getByRole('button', { name: 'Cancel' }));
    expect(onCancel).toHaveBeenCalledTimes(1);
    await act(async () => { resolve(response()); await Promise.resolve(); });
    await act(async () => { await vi.advanceTimersByTimeAsync(1000); });
    expect(onComplete).not.toHaveBeenCalled();
  });

  it('callback-only rerender does not issue another POST for the same mounted task', async () => {
    const fetchMock = vi.fn().mockReturnValue(new Promise(() => {}));
    vi.stubGlobal('fetch', fetchMock);
    const view = render(<ProcessingScreen {...props} onComplete={vi.fn()} onCancel={vi.fn()} />);
    await act(async () => { await vi.advanceTimersByTimeAsync(1); });
    view.rerender(<ProcessingScreen {...props} onComplete={vi.fn()} onCancel={vi.fn()} />);
    await act(async () => { await vi.advanceTimersByTimeAsync(1); });
    expect(fetchMock).toHaveBeenCalledTimes(1);
  });

  it('manual view and automatic timer share a single completion', async () => {
    const onComplete = vi.fn();
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue(response(true)));
    render(<ProcessingScreen {...props} onComplete={onComplete} onCancel={vi.fn()} />);
    await act(async () => { await vi.advanceTimersByTimeAsync(1); });
    const button = screen.getByTestId('view-results-btn');
    fireEvent.click(button); fireEvent.click(button);
    await act(async () => { await vi.advanceTimersByTimeAsync(2500); });
    expect(onComplete).toHaveBeenCalledTimes(1);
  });
});

